<span class="line"><span style="color:#0077B3;">Remember</span><span style="color:#68747D;">(</span><span style="color:#101820;">key </span><span style="color:#101820;">string</span><span style="color:#68747D;">,</span><span style="color:#101820;"> ttl time</span><span style="color:#68747D;">.</span><span style="color:#101820;">Duration</span><span style="color:#68747D;">,</span><span style="color:#101820;"> callback func</span><span style="color:#68747D;">()</span><span style="color:#101820;"> any</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> (</span><span style="color:#101820;">any</span><span style="color:#68747D;">,</span><span style="color:#101820;"> error</span><span style="color:#68747D;">)</span></span>
